import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../hooks/useAuth';

function Header() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  const handleLogout = () => {
    logout();
    navigate('/'); // 로그아웃 후 홈으로 이동
  };

  // 로그인 상태에 따라 '마이 리뷰', '마이 페이지'를 포함하는 메뉴 배열
  const mainNavLinks = [
    { path: '/', label: '영화 차트' },
    { path: '/search', label: '영화 검색' },
    { path: '/recommendations/movies', label: '추천 영화' },
    { path: '/recommendations/theaters', label: '추천 영화관' },
    { path: '/calendar', label: '캘린더' },
  ];

  if (user) {
    mainNavLinks.push(
      { path: '/my-reviews', label: '마이 리뷰' },
      { path: '/profile', label: '마이 페이지' }
    );
  }

  return (
    <header style={styles.header}>
      {/* 1. 왼쪽 로고 */}
      <Link to="/" style={styles.logo}>
        cineminu
      </Link>

      {/* 2. 중앙 메인 메뉴 */}
      <nav style={styles.nav}>
        {mainNavLinks.map((link) => (
          <Link key={link.path} to={link.path} style={styles.navLink}>
            {link.label}
          </Link>
        ))}
      </nav>

      {/* 3. 오른쪽 인증 메뉴 */}
      <div style={styles.authNav}>
        {user ? (
          <>
            {/* 로그인 시 '마이페이지'는 중앙 메뉴로 이동했으므로 여기서는 로그아웃 버튼만 표시 */}
            <button onClick={handleLogout} style={styles.authButton}>
              로그아웃
            </button>
          </>
        ) : (
          <>
            <Link to="/login" style={styles.authLink}>
              로그인
            </Link>
            <Link to="/signup" style={{ ...styles.authLink, ...styles.signupButton }}>
              회원가입
            </Link>
          </>
        )}
      </div>
    </header>
  );
}

// 스타일 객체
const styles = {
  header: {
    padding: '1rem 2rem',
    backgroundColor: '#ffffff', // 배경색을 흰색으로 변경
    borderBottom: '1px solid #e0e0e0', // 하단에 얇은 선 추가
    display: 'flex',
    justifyContent: 'space-between', // 양쪽 끝으로 요소를 배치하고 나머지는 중앙에
    alignItems: 'center', // 세로 중앙 정렬
    width: '100%',
    boxSizing: 'border-box',
  },
  logo: {
    textDecoration: 'none',
    color: 'black',
    fontWeight: 'bold',
    fontSize: '1.5rem',
  },
  nav: {
    display: 'flex',
    gap: '2rem', // 메뉴 아이템 사이의 간격
  },
  navLink: {
    textDecoration: 'none',
    color: '#333',
    fontWeight: '500',
    fontSize: '1rem',
    padding: '0.5rem 0',
    transition: 'color 0.2s',
  },
  authNav: {
    display: 'flex',
    alignItems: 'center',
    gap: '1rem',
  },
  authLink: {
    textDecoration: 'none',
    color: '#555',
    fontWeight: '500',
    padding: '0.5rem 1rem',
    borderRadius: '20px',
    transition: 'background-color 0.2s, color 0.2s',
  },
  signupButton: {
    backgroundColor: '#333',
    color: '#fff',
  },
  authButton: {
    backgroundColor: '#333',
    color: '#fff',
    border: 'none',
    padding: '0.5rem 1rem',
    borderRadius: '20px',
    cursor: 'pointer',
    fontWeight: '500',
    fontSize: '1rem',
  },
};

export default Header;
